<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); $id=(int)($_GET['id']??0); $album=['title'=>'','artist'=>'','description'=>'','cover_file'=>null]; if($id){$s=$pdo->prepare('SELECT * FROM albums WHERE id=?');$s->execute([$id]);$album=$s->fetch()?:$album;} if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$cover=$album['cover_file'];if(!empty($_FILES['cover']['name'])){$cover=upload_file($_FILES['cover'],dirname(__DIR__).'/uploads/covers',['image/jpeg','image/png','image/webp'],10*1024*1024);}if($id){$s=$pdo->prepare('UPDATE albums SET title=?,artist=?,description=?,cover_file=? WHERE id=?');$s->execute([trim($_POST['title']),trim($_POST['artist']),trim($_POST['description']),$cover,$id]);}else{$s=$pdo->prepare('INSERT INTO albums(title,artist,description,cover_file) VALUES(?,?,?,?)');$s->execute([trim($_POST['title']),trim($_POST['artist']),trim($_POST['description']),$cover]);$id=(int)$pdo->lastInsertId();}if(!empty($_FILES['tracks']['name'][0])){foreach($_FILES['tracks']['name'] as $i=>$name){$file=['name'=>$name,'type'=>$_FILES['tracks']['type'][$i],'tmp_name'=>$_FILES['tracks']['tmp_name'][$i],'error'=>$_FILES['tracks']['error'][$i],'size'=>$_FILES['tracks']['size'][$i]];$stored=upload_file($file,dirname(__DIR__).'/uploads/audio',['audio/mpeg','audio/wav','audio/x-wav','audio/flac','audio/mp4','audio/x-m4a','audio/ogg'],500*1024*1024);$title=pathinfo($name,PATHINFO_FILENAME);$s=$pdo->prepare('INSERT INTO tracks(album_id,title,track_no,audio_file,original_name,file_size) VALUES(?,?,?,?,?,?)');$s->execute([$id,$title,0,$stored,$name,$file['size']]);}}flash('success','Album gespeichert.');redirect('admin/album_edit.php?id='.$id);}catch(Throwable $e){flash('danger',$e->getMessage());redirect('admin/album_edit.php'.($id?'?id='.$id:''));}}$tracks=[];if($id){$s=$pdo->prepare('SELECT * FROM tracks WHERE album_id=? ORDER BY track_no,id');$s->execute([$id]);$tracks=$s->fetchAll();}render_header($id?'Album bearbeiten':'Neues Album',true);?><div class="d-flex justify-content-between mb-3"><h1 class="h2"><?=$id?'Album bearbeiten':'Neues Album'?></h1><?php if($id):?><a class="btn btn-outline-secondary" href="shares.php?album_id=<?=$id?>">Freigabelinks</a><?php endif?></div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="row g-4"><div class="col-lg-8"><div class="card shadow-sm"><div class="card-body"><div class="row g-3"><div class="col-md-7"><label class="form-label">Albumtitel</label><input class="form-control" name="title" value="<?=e($album['title'])?>" required></div><div class="col-md-5"><label class="form-label">Künstler</label><input class="form-control" name="artist" value="<?=e($album['artist'])?>"></div><div class="col-12"><label class="form-label">Beschreibung</label><textarea class="form-control" name="description" rows="4"><?=e($album['description'])?></textarea></div><div class="col-12"><label class="form-label">Titel hinzufügen</label><input class="form-control" type="file" name="tracks[]" accept="audio/*,.flac" multiple><div class="form-text">MP3, WAV, FLAC, M4A oder OGG. Mehrfachauswahl möglich.</div></div></div></div></div><?php if($tracks):?><div class="card shadow-sm mt-4"><div class="card-header">Vorhandene Titel</div><div class="list-group list-group-flush"><?php foreach($tracks as $t):?><div class="list-group-item d-flex justify-content-between align-items-center"><span><?=e($t['title'])?></span><a class="btn btn-sm btn-outline-danger" href="track_delete.php?id=<?=$t['id']?>&album_id=<?=$id?>&csrf=<?=csrf_token()?>" onclick="return confirm('Titel löschen?')">Löschen</a></div><?php endforeach?></div></div><?php endif?></div><div class="col-lg-4"><div class="card shadow-sm"><div class="card-body"><label class="form-label">Cover</label><?php if($album['cover_file']):?><img class="album-cover mb-3" src="<?=base_url('uploads/covers/'.$album['cover_file'])?>" alt=""><?php endif?><input class="form-control" type="file" name="cover" accept="image/jpeg,image/png,image/webp"><button class="btn btn-primary w-100 mt-3">Speichern</button></div></div></div></div></form><?php render_footer();
